{
  "events": [
    {
      "key": "axel_priest_supply",
      "choices": [
        {
          "index": 2,
          "label": "80골드로 돌을 맡길 자리를 마련하고 아쿠아와 비상분을 남긴다",
          "result": "당신은 80골드를 지불하고 아쿠아를 위해 돌을 놓을 자리를 마련하며 비상분 카드를 획득한다. 아쿠아는 자신의 돌이 돋보이는 자리에 놓이자 기뻐하며 당신을 향해 밝게 웃는다. 그녀는 칭찬을 기대하며 당신의 곁으로 바짝 다가와 앉는다."
        },
        {
          "index": 3,
          "label": "160골드로 돌아올 보급을 준비하고 아쿠아와 남길 몫을 나눈다",
          "result": "당신은 160골드를 들여 보급로를 확보하고 아쿠아와 나누어 가질 몫을 챙기며 돌아갈 곳부터 카드를 획득한다. 아쿠아는 보급품이 넉넉해지자 안심한 듯 가슴을 쓸어내리며 만족스러운 표정을 짓는다. 그녀는 당신의 세심한 배려에 감동한 듯 눈을 반짝이며 고개를 끄덕인다."
        }
      ]
    },
    {
      "key": "axel_crowded_road",
      "choices": [
        {
          "index": 3,
          "label": "160골드로 표식을 마련하고 다크니스 뒤의 공격 방향을 나눈다",
          "result": "당신은 160골드를 소모해 표식을 세우고 다크니스가 방어할 공간을 확보하며 검보다 먼저 선 자리 카드를 획득한다. 다크니스는 당신이 마련해 준 공격 공간을 확인하고는 더욱 굳건한 자세로 앞을 막아선다. 그녀는 자신의 방어에 기여해 준 당신을 향해 옅은 미소를 지으며 긍정한다."
        }
      ]
    },
    {
      "key": "axel_party_water",
      "choices": [
        {
          "index": 3,
          "label": "180골드로 짐 덮개를 마련하고 루나와 지나갈 자리를 비운다",
          "result": "당신은 180골드를 지불해 짐 덮개를 씌우고 루나와 이동 경로를 확보하며 창구 밖의 빈자리 카드를 획득한다. 루나는 짐이 안전하게 정리되자 안도의 한숨을 내쉬며 당신에게 고마움을 표한다. 그녀는 매끄러운 이동을 위해 당신과 눈을 맞추며 가볍게 고개를 끄덕인다."
        }
      ]
    },
    {
      "key": "axel_small_figure",
      "choices": [
        {
          "index": 3,
          "label": "160골드로 진열을 준비하고 크리스와 사람들이 지나갈 길을 나눈다",
          "result": "당신은 160골드를 써서 진열 공간을 정리하고 크리스와 통행로를 확보하며 흔적을 밟기 전에 카드를 획득한다. 크리스는 당신의 빠른 판단에 감탄하며 자연스럽게 옆으로 비켜 길을 터준다. 그녀는 효율적인 이동 경로를 확보한 것에 대해 만족스러운 듯 입꼬리를 올린다."
        }
      ]
    }
  ]
}
